begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "0111b956-12da-5637-8e52-580fd73fc028", "feature_slug": "stored-value-cards", "title": "1. Overview", "content": "Stored Value Cards are prepaid monetary cards that merchants issue to members. Unlike points (which are earned through activities), stored value cards carry a cash-equivalent balance loaded at creation time. A merchant defines card types (e.g., \"Gift Card ฿500\", \"VIP Prepaid ฿2,000\"), imports batches of uniquely numbered cards, and distributes them to members. Members spend the balance at participating locations until the card is depleted or expires.\n\nFor merchants, stored value cards solve two problems: (1) upfront revenue capture — the member pays for the card value before spending it, improving cash flow; (2) controlled distribution — physical or digital cards with unique numbers and security codes enable gift-giving, corporate bulk purchases, and promotional giveaways. The system tracks every transaction (assignment, redemption, top-up, expiry) in an immutable ledger, giving merchants full auditability.\n\nKey differentiators: (1) **three assignment methods** — automatic (system picks from pool), manual with security code (member self-activates), and manual without code (admin assigns directly); (2) **concurrent-safe assignment** — `FOR UPDATE SKIP LOCKED` prevents two members from receiving the same card; (3) **top-up support** — depleted cards can be recharged without creating a new card; (4) **batch import with validation** — cards are imported in bulk with duplicate detection and format validation (16-digit card numbers, 8-digit security codes).", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/stored-value-cards.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "stored-value-cards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0a3e5acf4439d432ab1e776afa6345f5c16dab65199e2b25210435b41bf37bf3", "truncated": false}, "is_active": true}, {"id": "5f83145a-64f2-5d8b-bce7-24119cd7e18b", "feature_slug": "stored-value-cards", "title": "8. Related Features", "content": "| Feature | Connection to Stored Value Cards |\n|---|---|\n| Currency | Cards use monetary value (not points). Both systems track balances but operate independently. See `Currency.md`. |\n| Rewards | Rewards consume points; cards consume monetary balance. Different spend mechanisms in the same loyalty program. See `Reward.md`. |\n| Mission | Missions can trigger automatic card assignment as a completion prize. See `Mission.md`. |\n| Tier | Tier upgrades can trigger card assignment. Card types could be tier-gated in future. See `Tier.md`. |\n| Activity/Earning | Activities earn points; card distribution is a separate value channel. See `Activity_Based_Earning.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/stored-value-cards.md#L312 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "stored-value-cards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0888f7e105b5ece84800e0be23d3d5b9d906c0abf4de42bcdc8c19ae1c089b92", "truncated": false}, "is_active": true}, {"id": "a96b7c5d-6a80-5ed2-a6d9-2bb2672bbde4", "feature_slug": "stored-value-cards", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Card with status `available` | Can be assigned (any method). Cannot be redeemed or topped up |\n| Card with status `assigned` | Can be redeemed and topped up. Cannot be re-assigned |\n| Card with status `depleted` | Can be topped up (returns to `assigned`). Cannot be redeemed |\n| Card with status `expired` | Cannot be assigned, redeemed, or topped up |\n| Assignment within window | Succeeds |\n| Assignment outside window (before start or after end) | Fails with window error |\n| Redeem amount > current_balance | Fails \"Insufficient balance\" with current_balance and requested_amount |\n| Redeem when expired | Fails, card status updated to `expired` |\n| Redeem before window_start | Fails \"Card cannot be used before [date]\" |\n| Top-up on expired card | Fails (status not in assigned/depleted) |\n| Top-up on depleted card | Succeeds, status returns to `assigned` |\n| Manual with wrong security code | Fails \"Invalid security code\" |\n| Manual with already-assigned card | Fails \"Card is not available for assignment\" |\n| Automatic when pool is empty | Fails \"No available cards of this type\" |\n| Import with duplicate card number | Entire batch rejected |\n| Import with 15-digit card number | Rejected \"invalid format\" |\n| Import with 7-digit security code | Rejected \"invalid security code\" |\n\n**Business rules as assertions:**\n\n- ASSERT: Automatic assignment picks the oldest imported card (FIFO by imported_at)\n- ASSERT: `FOR UPDATE SKIP LOCKED` prevents duplicate assignment under concurrency\n- ASSERT: Every balance change creates a ledger entry with correct balance_before and balance_after\n- ASSERT: balance_after = balance_before - amount (for redemption)\n- ASSERT: balance_after = balance_before + amount (for top-up)\n- ASSERT: Card status = `depleted` when current_balance reaches exactly 0 after redemption\n- ASSERT: Top-up on depleted card sets status back to `assigned`\n- ASSERT: `expire_cards` sets balance to 0, status to `expired`, assignment is_active to false\n- ASSERT: TTL expiry = assigned_at + ttl_months. Fixed expiry = card_type.fixed_expiry_date\n- ASSERT: Failed import batch stores duplicate/invalid card numbers in error_details JSONB\n\n**Status model (single track with transitions):**\n\n| From | To | Trigger |\n|---|---|---|\n| `available` | `assigned` | Any assignment method |\n| `assigned` | `depleted` | Redemption reduces balance to 0 |\n| `assigned` | `expired` | `expire_cards` job or redemption attempt on expired card |\n| `depleted` | `assigned` | Top-up adds balance |\n| `depleted` | `expired` | `expire_cards` job |\n\nInvalid transitions: `expired` → any state. `available` → `depleted`/`expired` directly.\n\n**Assignment deactivation states:**\n\n| is_active | deactivation_reason | Meaning |\n|---|---|---|\n| true | null | Active assignment |\n| false | `expired` | Card expired via `expire_cards` job |\n\n**Transaction types in ledger:**\n\n| Type | Amount meaning | When created |\n|---|---|---|\n| `assignment` | Initial value loaded | Card assigned to member |\n| `redemption` | Amount spent | Member uses balance |\n| `topup` | Amount added | Balance recharged |\n| `expiry` | Remaining balance forfeited | `expire_cards` job runs |\n\n**Error states to test:**\n\n- Concurrent automatic assignment (two requests, one card left → exactly one succeeds)\n- Top-up with amount = 0 or negative → \"Amount must be positive\"\n- Redeem with amount = 0 or negative → \"Amount must be positive\"\n- Check balance with wrong security code → \"Card not found or invalid credentials\"\n- Check balance without security code → returns card info (less secure path)\n- Assignment when card_type.is_active = false → \"Card type not found or inactive\"\n- Import batch with mix of valid and invalid cards → entire batch fails (all-or-nothing)", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/stored-value-cards.md#L164 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "stored-value-cards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e4a8615fa17d62c83b8421b60ab969adbc1153defe4162c6a9b63863548dc916", "truncated": false}, "is_active": true}, {"id": "253b3417-567b-52bd-8676-98b455097795", "feature_slug": "stored-value-cards", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n> **Note:** No dedicated member UI pages exist yet. The operations below are available as database functions and would be accessed through a future member app interface or API integration.\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| My Cards | _Not yet built_ | `get_user_cards(p_user_id)` |\n| Card Activation | _Not yet built_ | `assign_card_manual_with_code()` |\n| Card Balance Check | _Not yet built_ | `check_card_balance()` |\n| Card Transaction History | _Not yet built_ | `get_card_transactions(p_card_id)` |\n\n### 5a. Activate a Card (Self-Service)\n\n1. Member enters 16-digit card number and 8-digit security code (printed on physical card or received digitally)\n2. System calls `assign_card_manual_with_code`\n3. Validates: card exists, security code matches, status is `available`, within assignment window\n4. If wrong security code → \"Invalid security code\". If card already assigned → \"Card is not available for assignment\"\n5. On success: card assigned, expiry calculated, initial balance available immediately\n\n### 5b. Receive a Card (Automatic)\n\n1. Triggered by loyalty program action (e.g., mission completion, tier upgrade, campaign)\n2. System calls `assign_card_automatic` with member''s user_id and card_type_id\n3. System picks the oldest available card (FIFO) using `FOR UPDATE SKIP LOCKED`\n4. If no cards available → error \"No available cards of this type\"\n5. On success: member receives card with number, security code, expiry date, and balance\n\n### 5c. Use Card Balance\n\n1. Member presents card at point of sale (or uses online)\n2. System calls `redeem_card` with card_id and amount\n3. Validates: card status is `assigned`, not expired, sufficient balance, within usage window (window_start)\n4. On success: balance deducted, transaction recorded in ledger\n5. If balance reaches 0 → card status changes to `depleted`\n\n### 5d. Top Up a Card\n\n1. Member or admin requests top-up for an existing card\n2. System calls `topup_card` with card_id and amount\n3. Validates: card status is `assigned` or `depleted`, not expired, amount > 0\n4. On success: balance increased, transaction recorded. If card was `depleted`, status returns to `assigned`\n\n### 5e. View Cards and History\n\n1. Member views their cards via `get_user_cards` — shows all active, non-expired cards (optionally includes expired)\n2. Each card displays: card_number, card_type name, current_balance, initial_value, assigned_at, expires_at, is_expired, status\n3. Member views transaction history via `get_card_transactions` — paginated list (default 50 per page)\n4. Each transaction shows: type, amount, balance_before, balance_after, description, created_at", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/stored-value-cards.md#L111 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "stored-value-cards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "017377cf862a6a9cdd3305fcc3d54c3c381cf3f03fd8837b983619eec830f4d9", "truncated": false}, "is_active": true}, {"id": "a19aad11-d3b3-5d0c-ab89-96c009a0a2e6", "feature_slug": "stored-value-cards", "title": "6b. For Marketing", "content": "**Value proposition**: Stored value cards add a prepaid spending mechanism alongside points. Members receive cards through campaigns, tier upgrades, or direct purchase — creating immediate perceived value. Unlike points that accumulate gradually, a ฿500 gift card is instantly understood and motivating.\n\n**Use-case stories:**\n\n1. **Birthday campaign** — Members receive a ฿200 birthday gift card (automatic assignment via mission completion). Card expires in 3 months, creating urgency to visit. Cost to merchant: only realized when member spends.\n\n2. **Corporate bulk purchase** — Company buys 500 gift cards at ฿450 each (price) with ฿500 face value (card_value). Cards imported in one batch, distributed physically to employees. Each employee self-activates with card number + security code.\n\n3. **New member welcome** — Sign-up flow triggers automatic card assignment. New member immediately has ฿100 to spend, driving first purchase within the TTL window.\n\n4. **Top-up loyalty** — Members who deplete their card can top up, maintaining engagement. A depleted card becomes active again without needing a new card number.\n\n**Metrics merchants care about**: Cards issued vs. activated, average balance utilization (spent / initial_value), top-up rate, expiry forfeiture rate (balance lost to expiry), time-to-first-use.", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/stored-value-cards.md#L164 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "stored-value-cards", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7e4bab6bce0534922d24615836addcfb112aefcb033df23805fa017927074323", "truncated": false}, "is_active": true}, {"id": "2e6465ac-b77d-5f15-be2c-bff6f9207f5a", "feature_slug": "tags-and-personas", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Persona Group Settings | `/persona` | `bff_get_persona_structure()`, `upsert_persona_group_with_personas()` |\n| Customer 360 (search) | `/customer-360` | Customer search |\n| Customer 360 (detail) | `/customer-360/{userId}` | User profile with persona/tag data |\n\n### 4a. Manage Persona Groups and Personas\n\n1. Open **Persona Group Settings** — page displays existing groups as collapsible cards\n2. Click **\"+ Add persona group\"** — new empty card appends in expanded state\n3. Enter group name (required) and optionally select user_type (`buyer`, `seller`, or none)\n4. Click **\"+ Add persona\"** within the group card — new persona row appears\n5. Enter persona name, optionally upload an image (avatar for member-facing selector)\n6. Reorder personas using arrow buttons if needed\n7. Click **\"Save\"** — calls `upsert_persona_group_with_personas()` → page refreshes via RSC\n\n### 4b. Edit or Delete Groups and Personas\n\n1. From **Persona Group Settings**, click the edit icon on a group card → card expands with editable fields\n2. Modify group name, user_type, or persona rows → click **\"Save\"**\n3. To delete a persona: remove the row from the expanded card and save\n4. To delete a group: click the delete icon → confirmation dialog. Deletion is blocked if the group still contains personas — the RPC returns an error with the count of remaining personas\n5. Individual personas can also be deleted via `admin_delete_persona()`\n\n### 4c. Assign Persona or Tags to a Member\n\n1. Navigate to **Customer 360** → search for the member\n2. Open the member''s detail page — profile sidebar shows current persona and tags\n3. Use the edit profile panel to assign/change persona or add/remove tags\n4. Persona assignment calls `assign_persona()` — automatically updates user_type if the group specifies one\n5. Tag assignment calls `assign_tag()` with action `add` or `remove`\n\n### 4d. Common Admin Mistakes\n\n- Creating a persona group without user_type when the business requires buyer/seller distinction — members assigned personas from this group keep their existing user_type\n- Deleting a persona that members are currently assigned to — the persona_id on their account becomes a dangling reference\n- Assuming deactivating a persona group removes existing assignments — it only prevents new assignments", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/tags-and-personas.md#L58 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0011c165927e39d3a64826f95897168df8111744733a5c06527fadd5a3927d04", "truncated": false}, "is_active": true}, {"id": "48be35dd-52a0-552e-975c-3cb73ebf0e01", "feature_slug": "tags-and-personas", "title": "Current Production Status", "content": "### System Deployment\n- **Schema Version**: 1.0.0\n- **Tables Created**: 5 (4 new, 1 modified)\n- **Functions Deployed**: 2 (assign_persona, assign_tag)\n- **RLS Policies**: 8 active policies\n- **Indexes**: 6 performance indexes\n\n### Initial Data\n- **Persona Groups**: 3 (Corporate Members, Student, Distributor)\n- **Personas**: 8 across all groups\n- **Tags**: 6 (VIP, Early Adopter, Frequent Buyer, Influencer, At Risk, New Customer)\n- **Test Coverage**: 100% of core functions tested\n\n### Performance Metrics\n- **Persona Assignment**: < 10ms average\n- **Tag Assignment**: < 5ms average\n- **Bulk Operations**: 1000 assignments/second\n- **Query Performance**: All indexed queries < 50ms\n\n### Validation Results\n\n| Test Case | Expected | Actual | Status |\n|-----------|----------|--------|--------|\n| Assign persona with user_type | Type changes | ✅ Type changed | PASS |\n| Assign persona without user_type | Type unchanged | ✅ Type unchanged | PASS |\n| Add tag | Tag assigned | ✅ Tag assigned | PASS |\n| Remove tag | Tag removed | ✅ Tag removed | PASS |\n| Duplicate tag prevention | No duplicate | ✅ Prevented | PASS |\n| Cross-merchant validation | Rejected | ✅ Rejected | PASS |\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Tag_and_Persona.md#L1016 Current Production Status", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7b0879eed858c54aa690fe823e5223b4ea201273a4bac9b6b15dac904d4743db", "truncated": false}, "is_active": true}, {"id": "c403e4c5-7353-52d8-8069-8c655e6abeeb", "feature_slug": "tags-and-personas", "title": "Business Rules Summary", "content": "### Core Principles\n1. **Single Persona Rule**: Each user can have at most one persona\n2. **Multiple Tags Rule**: Users can have unlimited tags\n3. **Group Inheritance**: Personas inherit all group configurations\n4. **User Type Automation**: Persona assignment can update user_type\n5. **Merchant Isolation**: All data is merchant-scoped\n6. **Active Status Respect**: Inactive personas/tags cannot be assigned\n\n### Assignment Rules\n\n#### Persona Assignment\n- Assigning a persona from a group with user_type updates the user''s type\n- Removing a persona (NULL assignment) does not revert user_type\n- Inactive personas or groups cannot be assigned\n- Cross-merchant persona assignment is blocked\n\n#### Tag Assignment  \n- Duplicate tag assignments are silently ignored (idempotent)\n- Tag removal of non-existent assignments returns success\n- Tags must belong to the same merchant as the user\n- Inactive tags cannot be assigned\n\n### Data Integrity Rules\n- Foreign key constraints ensure referential integrity\n- Unique constraints prevent duplicate assignments\n- Cascade deletes clean up orphaned records\n- RLS policies enforce merchant boundaries\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Tag_and_Persona.md#L897 Business Rules Summary", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c3937c37f58ed34a2d67c87eb3d192469914972964abfc57ac1867a49c5a7d50", "truncated": false}, "is_active": true}, {"id": "f092abe4-e761-5f4e-b394-06b34cb7a6f9", "feature_slug": "tags-and-personas", "title": "7. Business Rules", "content": "**Rule:** Each member has at most one persona. Assigning a new persona replaces the existing one.\n**Example:** Member has \"SME\" persona → assigned \"Corporation\" → member now has \"Corporation\", \"SME\" is gone.\n\n**Rule:** Persona groups optionally define a `user_type`. When a persona is assigned, the member''s user_type updates to the group''s value if one is set.\n**Example:** \"Corporate Members\" group has `user_type=seller`. Assigning any persona from this group changes the member to `seller`.\n\n**Rule:** Removing a persona (setting to null) does not revert user_type. The last user_type set by a persona assignment persists.\n**Example:** Member was `buyer` → assigned \"SME\" (seller group) → became `seller` → persona removed → member stays `seller`.\n\n**Rule:** Members can have unlimited tags. Tags are independent — no hierarchy or grouping.\n**Example:** Member can simultaneously be tagged \"VIP\", \"Influencer\", \"Early Adopter\", \"Frequent Buyer\".\n\n**Rule:** Tag operations are idempotent. Adding an existing tag or removing a non-existent tag returns success without error.\n**Example:** `assign_tag(user, vip_tag, ''add'')` called twice → one `user_tags` record, two success responses.\n\n**Rule:** All personas, groups, and tags are merchant-scoped. Cross-merchant assignment is blocked at the function level.\n**Example:** Tag belonging to Merchant A cannot be assigned to a user belonging to Merchant B.\n\n**Rule:** Deactivating a persona, group, or tag prevents new assignments but does not remove existing ones.\n**Example:** Deactivating \"VIP\" tag → members who already have it keep it, but no new members can receive it.\n\n**Rule:** A persona group cannot be deleted while it still contains personas. Delete or reassign all child personas first.\n**Example:** Attempting to delete \"Corporate Members\" with 3 personas → error response with count.\n\n**Rule:** Persona and tag names must be unique per merchant.\n**Example:** Two tags named \"VIP\" under the same merchant → blocked by unique constraint.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L216 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "49ae055027069846a538bf4032730ac687b413e3203555bfb69f216b640a909d", "truncated": false}, "is_active": true}, {"id": "0119db0c-871c-57c2-8875-7426f06ea052", "feature_slug": "tags-and-personas", "title": "3. Configuration Reference", "content": "### Persona Group\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Group name | Display name of the category | \"Corporate Members\" | Required |\n| Description | Purpose explanation | \"B2B customer segments\" | Empty |\n| User type | Auto-assigned user_type for personas in this group | `seller` | null (no change) |\n| Active status | Whether group''s personas can be assigned | true | true |\n| Config (jsonb) | Reserved for future group-level settings | `{}` | `{}` |\n\n### Persona\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Persona name | Display name shown to members and admins | \"SME\" | Required |\n| Description | What this persona represents | \"Small/medium enterprises\" | Empty |\n| Group | Parent persona group (required) | \"Corporate Members\" | Required |\n| Image | Avatar shown in signup persona selector | CDN URL | null |\n| Active status | Whether this persona can be assigned | true | true |\n| Config (jsonb) | Reserved for persona-specific settings | `{}` | `{}` |\n\n### Tag\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Tag name | Identifier for the tag | \"VIP\" | Required |\n| Description | What this tag represents | \"High-value customer\" | Empty |\n| Active status | Whether this tag can be assigned | true | true |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/tags-and-personas.md#L27 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5196a2035850d659ee79d7c29f3b09699b4996eabab4e2ea7142314e0dbee9dd", "truncated": false}, "is_active": true}, {"id": "955e9d47-3a05-5439-abec-51913a1dc215", "feature_slug": "tags-and-personas", "title": "Core Tables and Structure", "content": "### 1. persona_group_master Table\nThis table defines persona categories with group-level configurations. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the persona group |\n| `merchant_id` | uuid | Links to the merchant who owns this group |\n| `group_name` | text | Display name of the group (e.g., \"Corporate Members\", \"Student\") |\n| `description` | text | Detailed description of the group''s purpose |\n| `user_type` | enum | Optional user_type (''buyer'' or ''seller'') to assign when personas in this group are selected |\n| `config` | jsonb | Extensible configuration object for future group-level settings |\n| `metadata` | jsonb | Additional metadata storage |\n| `active_status` | boolean | Whether this group is currently active |\n| `created_at` | timestamptz | Timestamp of group creation |\n| `updated_at` | timestamptz | Timestamp of last update |\n\n**Business Rules**:\n- Group names must be unique per merchant\n- User_type at group level is optional but recommended for consistency\n- Deactivating a group does not remove existing persona assignments\n\n### 2. persona_master Table\nThis table defines individual personas within groups. Key fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the persona |\n| `merchant_id` | uuid | Links to the merchant |\n| `group_id` | uuid | References the parent group in persona_group_master |\n| `persona_name` | text | Display name of the persona (e.g., \"SME\", \"University\", \"Tier 1 Dealer\") |\n| `description` | text | Detailed description of the persona |\n| `config` | jsonb | Extensible configuration for persona-specific settings |\n| `metadata` | jsonb | Additional metadata storage |\n| `active_status` | boolean | Whether this persona is currently active |\n| `created_at` | timestamptz | Timestamp of persona creation |\n| `updated_at` | timestamptz | Timestamp of last update |\n\n**Business Rules**:\n- Persona names must be unique per merchant\n- Personas must belong to exactly one group\n- Personas inherit all group-level configurations unless overridden\n\n### 3. tag_master Table\nThis table defines available tags for customer labeling. Fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the tag |\n| `merchant_id` | uuid | Links to the merchant |\n| `tag_name` | text | Display name of the tag (e.g., \"VIP\", \"At Risk\") |\n| `description` | text | Explanation of what this tag represents |\n| `active_status` | boolean | Whether this tag is currently active |\n| `created_at` | timestamptz | Timestamp of tag creation |\n| `updated_at` | timestamptz | Timestamp of last update |\n\n**Business Rules**:\n- Tag names must be unique per merchant\n- Tags are independent entities (no hierarchical relationships)\n- Deactivating a tag does not remove existing assignments\n\n### 4. user_tags Table\nThis junction table manages the many-to-many relationship between users and tags. Fields include:\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | Unique identifier for the assignment |\n| `user_id` | uuid | References user in user_accounts |\n| `tag_id` | uuid | References tag in tag_master |\n| `merchant_id` | uuid | Links to merchant for data partitioning |\n| `created_at` | timestamptz | Timestamp when tag was assigned |\n\n**Business Rules**:\n- Unique constraint on (user_id, tag_id) prevents duplicate assignments\n- Cascade delete ensures cleanup when users or tags are removed\n- Merchant_id enables efficient data partitioning and access control\n\n### 5. user_accounts Table (persona-relevant fields)\n\n| Field | Type | Purpose |\n|-------|------|---------|\n| `id` | uuid | User identifier (references auth.users) |\n| `merchant_id` | uuid | Links to merchant |\n| `user_type` | enum | ''buyer'' or ''seller'' - can be updated by persona assignment |\n| `persona_id` | uuid | Current persona assignment (references persona_master) |\n| `tier_id` | uuid | Current tier assignment (existing field) |", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Tag_and_Persona.md#L35 Core Tables and Structure", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d6427c13bf573ec39af5f435e5f86784c5789b4f82fa6d740bc45e715f2d20ca", "truncated": false}, "is_active": true}, {"id": "51bf8a2c-8405-5691-a2b6-a13171e7c183", "feature_slug": "tags-and-personas", "title": "API Integration", "content": "### Persona Assignment API\n```http\nPOST /api/users/{user_id}/persona\n```\n\nRequest:\n```json\n{\n  \"persona_id\": \"uuid\",\n  \"reason\": \"Customer business verification completed\"\n}\n```\n\nResponse:\n```json\n{\n  \"success\": true,\n  \"data\": {\n    \"user_id\": \"uuid\",\n    \"persona\": {\n      \"id\": \"uuid\",\n      \"name\": \"SME\",\n      \"group\": \"Corporate Members\"\n    },\n    \"user_type_changed\": true,\n    \"old_user_type\": \"buyer\",\n    \"new_user_type\": \"seller\"\n  }\n}\n```\n\n### Tag Management API\n\n#### Add Tag\n```http\nPOST /api/users/{user_id}/tags\n```\n\nRequest:\n```json\n{\n  \"tag_id\": \"uuid\"\n}\n```\n\n#### Remove Tag\n```http\nDELETE /api/users/{user_id}/tags/{tag_id}\n```\n\n#### List User Tags\n```http\nGET /api/users/{user_id}/tags\n```\n\nResponse:\n```json\n{\n  \"tags\": [\n    {\n      \"id\": \"uuid\",\n      \"name\": \"VIP\",\n      \"assigned_at\": \"2024-01-15T10:30:00Z\"\n    },\n    {\n      \"id\": \"uuid\",\n      \"name\": \"Early Adopter\",\n      \"assigned_at\": \"2024-01-10T08:00:00Z\"\n    }\n  ]\n}\n```\n\n### Bulk Operations API\n\n#### Bulk Tag Assignment\n```http\nPOST /api/tags/bulk-assign\n```\n\nRequest:\n```json\n{\n  \"tag_id\": \"uuid\",\n  \"user_ids\": [\"uuid1\", \"uuid2\", \"uuid3\"],\n  \"action\": \"add\"\n}\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/Tag_and_Persona.md#L804 API Integration", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "e5fd7cfa0b14b7fa85b4e3bdacf825b55c7765a9176f0f11bc56eecb61616fc1", "truncated": false}, "is_active": true}, {"id": "1edf7856-de5c-5c09-98ff-0679b51678e7", "feature_slug": "tags-and-personas", "title": "2. Key Concepts", "content": "**Persona** — A member''s primary business classification. Stored as `persona_id` on the user account. Each member has zero or one persona. Example: \"SME\" under the \"Corporate Members\" group.\n\n**Persona Group** — A parent category that contains personas and optionally defines a `user_type`. All personas in a group share the group''s user_type behavior. Example: \"Corporate Members\" (user_type=seller) contains \"SME\", \"Corporation\", \"Enterprise\".\n\n**Tag** — An independent label attached to a member. Many-to-many: a member can have any number of tags, and a tag can be assigned to any number of members. Example: \"VIP\", \"At Risk\", \"Frequent Buyer\".\n\n**User Type** — An enum on user_accounts with values `buyer` or `seller`. Persona assignment can auto-update this value based on the persona group''s configuration. Removing a persona does not revert user_type.\n\n**Merchant Isolation** — All personas, persona groups, and tags are scoped to a single merchant. Cross-merchant assignment is blocked at the function level.\n\n**Idempotent Operations** — Adding a tag that already exists returns success without creating a duplicate. Removing a tag that isn''t assigned returns success. Duplicate-safe by design.\n\n**Active Status** — Personas, persona groups, and tags each have an `active_status` flag. Inactive items cannot be newly assigned but existing assignments are not removed when an item is deactivated.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6d19e380285989179b5ead4bed80a54a55bf81e08800720d1f4be948a064e40f", "truncated": false}, "is_active": true}, {"id": "2bb5243e-9748-5931-ad9c-1a73a55f463b", "feature_slug": "tags-and-personas", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Personas are your customers'' business profiles — Corporate, Student, Distributor. Each customer gets one. Tags are flexible labels — VIP, At Risk, Influencer — and customers can have as many as needed. Together, they let you target rewards, pricing, and campaigns to the right segments.\"\n\n**Common questions:**\n\n| Question | Answer |\n|---|---|\n| \"What''s the difference between persona and tag?\" | Persona = business profile (one per member, can change user_type). Tag = behavioral label (unlimited per member, no side effects). |\n| \"A member''s user_type changed unexpectedly\" | Check if a persona was recently assigned from a group with a user_type setting. Persona assignment auto-updates user_type. |\n| \"Can we undo a user_type change?\" | Removing the persona does not revert user_type. You must manually update user_type or assign a persona from a group with the desired user_type. |\n| \"A tag was assigned twice\" | Not possible — the system prevents duplicates. The second assignment returns success without creating a new record. |\n| \"Deactivated a persona but members still have it\" | Deactivating prevents new assignments only. Existing assignments persist until explicitly changed. |\n| \"Member didn''t see persona selection during signup\" | Merchant may not have the persona system enabled, or all persona groups are inactive. Check `bff_get_persona_structure()` returns data. |\n\n**Config mistakes → fix:**\n\n| Mistake | Symptom | Fix |\n|---|---|---|\n| Persona group has no user_type set | Members assigned personas keep their old user_type | Set user_type on the group if buyer/seller distinction is needed |\n| All persona groups deactivated | Persona step skipped in signup, no personas assignable | Reactivate at least one group |\n| Persona deleted while members assigned to it | Dangling `persona_id` on user accounts | Reassign affected members to a new persona or set to null |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L131 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "6beb00280c63437db3a0739a60c682e5be6ad3fe4757242dfedd8a978a1a2f88", "truncated": false}, "is_active": true}, {"id": "9e408e28-9193-5e3f-b5da-51deaaeddd9f", "feature_slug": "tags-and-personas", "title": "1. Overview", "content": "Tags and personas are two complementary classification systems that let merchants segment their customer base beyond tiers. Personas represent a member''s business profile — Corporate, Student, Distributor — and each member can have at most one. Tags are behavioral markers — VIP, At Risk, Early Adopter — and a member can carry unlimited tags. Together they form two of the four dimensions (alongside tier and user_type) that other features use for eligibility filtering and dynamic pricing.\n\nPersonas are organized into groups, and each group can optionally specify a user_type (buyer or seller). When a member is assigned a persona, the system automatically updates their user_type to match the group''s setting. This means persona assignment doubles as a user_type management tool — a merchant doesn''t need to manually set buyer/seller status if their persona groups already encode it.\n\nTags serve a different purpose: flexible, additive labeling for behavioral attributes and marketing segmentation. A member tagged \"VIP\" and \"Influencer\" can be targeted by campaigns, granted special reward eligibility, or routed to priority support. Unlike personas, tags have no hierarchy and no side effects on other fields.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a1ebd097bbb4a696552da92ae25caeff892f76ad0f89faa9cf631b5b08077760", "truncated": false}, "is_active": true}, {"id": "0a9fb76d-e209-56aa-9d9e-5a2fa6c2a9f9", "feature_slug": "tags-and-personas", "title": "8. Related Features", "content": "| Feature | Connection to Tags & Personas |\n|---|---|\n| Rewards | Personas and tags are eligibility dimensions and dynamic pricing dimensions. See `Reward.md`. |\n| Tier | Tier + persona + tags together form the segmentation stack. Tier evaluations can factor in persona. See `Tier.md`. |\n| Currency | Earn rules can use persona for personalized earn factors (e.g., Corporate earns 2x). See `Currency.md`. |\n| Forms | Profile form includes persona selection step during signup. Persona-aware conditional fields can show/hide based on selected persona. See `Forms.md`. |\n| Missions | Mission eligibility can be filtered by persona and tags. See `Mission.md`. |\n| AMP Workflows | Automation workflows can use persona/tag as audience conditions for targeted campaigns. See `AMP - Rule Based.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L245 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a8cf9bc97782ba088a1a746d1b990ee3e654276266a4582c4fd5ad42a76e0a05", "truncated": false}, "is_active": true}, {"id": "3bd4778c-ed23-55ef-b040-8fb3d4b19bc9", "feature_slug": "tags-and-personas", "title": "System Flow Diagrams", "content": "### Complete Persona Assignment Flow\n\n```mermaid\nsequenceDiagram\n    participant Admin\n    participant API\n    participant assign_persona\n    participant DB\n    participant user_accounts\n    \n    Admin->>API: Request persona assignment\n    API->>assign_persona: assign_persona(user_id, persona_id)\n    \n    assign_persona->>user_accounts: Fetch current user state\n    user_accounts-->>assign_persona: Current persona & user_type\n    \n    assign_persona->>DB: Get persona details\n    DB->>DB: JOIN persona_master + persona_group_master\n    DB-->>assign_persona: Persona info + group config\n    \n    assign_persona->>assign_persona: Validate active status\n    \n    alt Group has user_type\n        assign_persona->>assign_persona: Use group user_type\n    else No group user_type\n        assign_persona->>assign_persona: Keep current user_type\n    end\n    \n    assign_persona->>user_accounts: UPDATE persona_id, user_type\n    user_accounts-->>assign_persona: Update confirmed\n    \n    assign_persona-->>API: Return success with details\n    API-->>Admin: Display confirmation\n    \n    Note over Admin: User now has:<br/>- New persona<br/>- Possibly new user_type<br/>- Audit trail created\n```\n\n### Tag Management Flow\n\n```mermaid\ngraph TD\n    subgraph \"Tag Addition Flow\"\n        A1[Add Tag Request] --> B1{User Exists?}\n        B1 -->|No| C1[Error: User not found]\n        B1 -->|Yes| D1{Tag Valid?}\n        D1 -->|No| E1[Error: Invalid tag]\n        D1 -->|Yes| F1{Same Merchant?}\n        F1 -->|No| G1[Error: Wrong merchant]\n        F1 -->|Yes| H1{Already Tagged?}\n        H1 -->|Yes| I1[Return: Already assigned]\n        H1 -->|No| J1[INSERT user_tags]\n        J1 --> K1[Success: Tag added]\n    end\n    \n    subgraph \"Tag Removal Flow\"\n        A2[Remove Tag Request] --> B2{Tag Assigned?}\n        B2 -->|No| C2[Return: Not assigned]\n        B2 -->|Yes| D2[DELETE from user_tags]\n        D2 --> E2[Success: Tag removed]\n    end\n    \n    style K1 fill:#c8e6c9\n    style E2 fill:#c8e6c9\n    style C1 fill:#ffcdd2\n    style E1 fill:#ffcdd2\n    style G1 fill:#ffcdd2\n```\n\n### Data Relationships\n\n```mermaid\nerDiagram\n    user_accounts ||--o| persona_master : \"has persona\"\n    persona_master }o--|| persona_group_master : \"belongs to\"\n    user_accounts ||--o{ user_tags : \"has tags\"\n    user_tags }o--|| tag_master : \"references\"\n    \n    user_accounts {\n        uuid id PK\n        uuid merchant_id FK\n        uuid persona_id FK \"NULL allowed\"\n        user_type user_type\n        uuid tier_id FK\n    }\n    \n    persona_group_master {\n        uuid id PK\n        uuid merchant_id FK\n        text group_name\n        user_type user_type \"optional\"\n        boolean active_status\n    }\n    \n    persona_master {\n        uuid id PK\n        uuid merchant_id FK\n        uuid group_id FK\n        text persona_name\n        boolean active_status\n    }\n    \n    tag_master {\n        uuid id PK\n        uuid merchant_id FK\n        text tag_name\n        boolean active_status\n    }\n    \n    user_tags {\n        uuid id PK\n        uuid user_id FK\n        uuid tag_id FK\n        uuid merchant_id FK\n        timestamptz created_at\n    }\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Tag_and_Persona.md#L408 System Flow Diagrams", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3405e530bd426e57b0bdbede9d45108904fee5032691910793a2a7d848d5a4a8", "truncated": false}, "is_active": true}, {"id": "d345fd58-790b-5098-9409-1d142cc47e07", "feature_slug": "tags-and-personas", "title": "Tag & Persona Domain Reference", "content": "**Keywords:** tag, persona, segment, persona group, user type, buyer, seller, VIP, classification, behavioral marker, assign persona, assign tag, user tags\n**Source:** `Tag_and_Persona.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `assign_persona(p_user_id, p_persona_id)` | `p_user_id (uuid)`, `p_persona_id (uuid, nullable)` | JSONB: success, persona name, group name, user_type change indicator | 285–318 |\n| `assign_tag(p_user_id, p_tag_id, p_action)` | `p_user_id (uuid)`, `p_tag_id (uuid)`, `p_action (''add''/''remove'')` | JSONB: success, tag name, action taken | 319–352 |\n**Key Business Rules (summary):**\n- Users have exactly one persona (or none) — represents business profile\n- Users can have unlimited tags — represents behavioral attributes\n- Assigning a persona from a group with `user_type` automatically updates the user''s `user_type`\n- Removing persona does NOT revert user_type\n- Tags are idempotent: adding an already-assigned tag returns success silently\n- All operations enforce merchant isolation", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/tag-persona.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c575f7819fff4f52ea3e7e7d115268ee55741ad5b9631a52f80130ed44266164", "truncated": false}, "is_active": true}, {"id": "1ecea068-e1dc-5599-a37d-7bdd9a88049c", "feature_slug": "tags-and-personas", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| Assign persona from group with `user_type=seller` | Member''s user_type changes to `seller` |\n| Assign persona from group with `user_type=null` | Member''s user_type unchanged |\n| Remove persona (set to null) | `persona_id` cleared, user_type unchanged |\n| Add tag to member | `user_tags` record created |\n| Add same tag again | Success response, no duplicate record |\n| Remove tag from member | `user_tags` record deleted |\n| Remove tag not assigned | Success response, no error |\n| Assign inactive persona | Error returned, assignment blocked |\n| Assign tag from different merchant | Error: \"Tag belongs to different merchant\" |\n| Deactivate persona group | Existing assignments persist, new assignments blocked |\n\n**Business rules as assertions:**\n\n- ASSERT: A member has at most one `persona_id` at any time\n- ASSERT: A member can have unlimited tags (no upper bound enforced)\n- ASSERT: Persona assignment from a group with user_type updates `user_accounts.user_type`\n- ASSERT: Persona removal sets `persona_id = null` but does not change `user_type`\n- ASSERT: Tag add is idempotent — duplicate calls produce exactly one `user_tags` record\n- ASSERT: Tag remove is idempotent — removing a non-existent assignment returns success\n- ASSERT: Cross-merchant persona/tag assignment is rejected\n- ASSERT: Inactive persona/tag assignment is rejected\n- ASSERT: Deleting a persona group with existing personas is blocked\n\n**Cross-feature scenarios to test:**\n\n- Assign persona → check reward eligibility updates (persona is an eligibility dimension)\n- Assign persona → check dynamic pricing changes (persona is a pricing dimension)\n- Add tag → check reward eligibility updates (tags are an eligibility dimension)\n- Change persona from group A (seller) to group B (buyer) → verify user_type changes to buyer\n- Remove persona → verify user_type stays at last-set value\n- Signup flow: select persona during registration → verify persona_id saved on user_accounts\n- Signup flow: merchant without persona system → verify persona step is skipped", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L131 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "18232b5ce2c355db48a5bcffc7eb057415d0f6446df8a056fcaa01ed65f247eb", "truncated": false}, "is_active": true}, {"id": "317a6397-8b59-5d66-8f83-ee2406df1ce6", "feature_slug": "tags-and-personas", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Signup Drawer (persona step) | Bottom-sheet on any page | `bff-auth-complete` → `missing_data` payload |\n| Profile Page | `/profile` | `get_user_summary()` |\n| Edit Profile Drawer | Bottom-sheet on `/profile` | `bff_get_user_profile_template(mode=''edit'')` |\n\n### 5a. Persona Selection During Signup\n\n1. After authentication, the signup drawer advances through form steps: **persona** → default fields → custom fields → PDPA\n2. The persona step renders a **PersonaSelector** — a 4-column avatar grid grouped by persona group name\n3. Each avatar shows the persona image (or first letter fallback) with the persona name below\n4. Member taps one avatar → ring highlight + checkmark appears on the selected persona\n5. Only one persona can be selected. Tapping another replaces the selection.\n6. The persona step is skipped entirely if the merchant does not use the persona system\n7. On final form submission, `bff_save_user_profile` persists the selected persona_id\n\n### 5b. Persona on Profile\n\n1. The member''s assigned persona is part of their profile data returned by `get_user_summary()`\n2. The Edit Profile drawer fetches `bff_get_user_profile_template(mode=''edit'')` — if the template includes persona data, the member can view or change their persona\n3. Members do not manage their own tags — tags are admin-assigned or API-assigned only\n4. Tags affect what the member sees indirectly: other features (rewards, missions) use tags as eligibility filters, so a tagged member may see different content than an untagged one", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/tags-and-personas.md#L102 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "05d0cc06c1941681c15376c8c346aa8e51cfb76187184fd9403117e254295b76", "truncated": false}, "is_active": true}, {"id": "416842c7-e56b-536d-b9d0-bc8ccf3f1cd0", "feature_slug": "tags-and-personas", "title": "6b. For Marketing", "content": "**Value proposition:** Tags and personas add two segmentation dimensions on top of tiers. Personas classify members by business profile (B2B vs B2C, student vs corporate), while tags capture behavioral signals (engagement level, risk status, influencer potential). Both feed into the eligibility and dynamic pricing engines across rewards, missions, and earn rules.\n\n**Segmentation use cases:**\n1. **Persona-based pricing** — \"Corporate\" members pay 60 points for a reward, \"Student\" members pay 40 points (via dynamic pricing conditions on the reward)\n2. **Tag-driven campaigns** — Target \"At Risk\" tagged members with retention rewards; target \"VIP\" tagged members with exclusive early-access offers via AMP workflows\n3. **Combined targeting** — Reward eligibility restricted to \"Corporate\" persona + \"VIP\" tag = only high-value business customers qualify\n4. **Lifecycle management** — Tag new signups as \"New Customer\", auto-tag based on purchase patterns, retarget \"Dormant\" tagged members\n5. **B2B user type automation** — Create persona groups with `user_type=seller` for distributors and resellers. When a member selects their business persona during signup, they''re automatically classified as a seller without manual intervention\n\n**When to use persona vs. tag:**\n\n| Use case | Persona | Tag |\n|---|---|---|\n| Business type classification (SME, Corporation, Student) | Yes | — |\n| Customer value indicator (VIP, High Spender) | — | Yes |\n| Lifecycle stage (New, Active, Dormant, Churned) | — | Yes |\n| Organization role (Distributor, Reseller, Franchise) | Yes | — |\n| Behavioral signal (Early Adopter, Influencer, At Risk) | — | Yes |", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/tags-and-personas.md#L131 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tags-and-personas", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "90d4805d3a4d0eaf6e30143ebb52ccf09db7484fd49076e30609b6e0d04a464b", "truncated": false}, "is_active": true}, {"id": "da6d5794-9550-5d8f-8d70-ff3ed646dbc5", "feature_slug": "tiers", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n\n| Page name                         | Current route                    | BFF / data source                              |\n| --------------------------------- | -------------------------------- | ---------------------------------------------- |\n| Tier List                         | `/tier`                          | `get_merchant_tiers(p_merchant_id)`            |\n| Tier Conditions Settings (create) | `/tier-conditions-settings/new`  | `get_tier_conditions_by_type(mode=''new'')`      |\n| Tier Conditions Settings (edit)   | `/tier-conditions-settings/{id}` | `get_tier_conditions_by_type(mode=''edit'', id)` |\n\n\n### 4a. Create a New Tier\n\n1. From **Tier List**, click **\"Add tier\"** button\n2. **Tier Conditions Settings** opens in create mode — empty form\n3. Fill in tier name (required), select user type (buyer/seller), optionally select a persona\n4. Set ranking to position this tier in the hierarchy\n5. Toggle entry tier if this is the default for new members\n6. Optionally set burn rate for points-to-discount conversion\n7. Add upgrade conditions via repeatable rows: select metric (points/tickets/sales/orders), set target amount, choose window type and period\n8. Add maintain conditions (same fields as upgrade)\n9. Click **\"Save\"**\n10. On success: redirect to **Tier List**\n\n### 4b. Edit an Existing Tier\n\n1. From **Tier List**, click any tier row or the edit icon\n2. **Tier Conditions Settings** opens in edit mode — form pre-populated with current values and conditions\n3. Modify any fields — add/remove/edit conditions\n4. Save updates\n\n### 4c. Manage Tier List\n\n1. **Tier List** displays all tiers with columns: name, ranking, user type, persona, entry tier badge, burn rate, condition count\n2. Tiers are ordered by ranking\n3. **Reorder**: drag or use reorder function to change ranking positions (`reorder_tiers`)\n4. **Delete**: click delete → confirmation modal. Deletion blocked if members are assigned to the tier\n5. **Display settings**: configure icon, color, benefits, and card design per tier (`bff_upsert_tier_display`)\n\n### 4d. View Tier Change History\n\nAdmin can view tier change history for members, showing upgrade/downgrade/initial/manual changes with timestamps and reasons.\n\n### 4e. Common Admin Mistakes\n\n- Creating multiple entry tiers for the same user_type/persona → only one is used (first found)\n- Setting ranking gaps (1, 2, 5) → works but confuses the visual hierarchy\n- No maintain conditions on a tier → members never get downgraded from it\n- Persona-scoped tiers without matching entry tier → new members of that persona get no tier\n- Setting metric to `ticket` when the merchant only uses points → zero progress for everyone\n- Window type `anniversary` without understanding that each member''s window starts from their signup date", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/tiers.md#L94 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5e4c598f581865a01d365a50d26daf6f518d63313d295d6565e721c538e41f1a", "truncated": false}, "is_active": true}, {"id": "96ba3c62-7811-5baa-bd93-a10d7520909d", "feature_slug": "tiers", "title": "Current Production Status & Test Validation", "content": "### System Health\n- **Total Users**: 13 with complete tier assignments\n- **Progress Records**: 13 (100% coverage)\n- **Tier Changes**: 25 automatic changes processed\n- **Queue Status**: Empty (all messages processed successfully)\n- **Health Status**: HEALTHY (normal operation)\n- **Error Rate**: 0% (no processing errors)\n\n### Tier Distribution\n- **Bronze**: 9 users (including downgrades and new entries)\n- **Silver**: 0 users (all qualified users skipped to Gold)\n- **Gold**: 3 users (successful tier skipping demonstrated)\n- **Platinum**: 1 user (high performer)\n- **Diamond**: 0 users (highest tier, requires exceptional performance)\n\n### Tier Progression Validation\n\n| User Type | Points 6mo | Expected Tier | Actual Tier | Progression Type |\n|-----------|------------|---------------|-------------|------------------|\n| High Performer | 10,000 | Platinum | ✅ Platinum | Bronze → **Skipped Silver & Gold** → Platinum |\n| Steady Climber | 1,800 | Gold | ✅ Gold | Bronze → **Skipped Silver** → Gold |\n| Edge Case | 1,550 | Gold | ✅ Gold | Bronze → **Skipped Silver** → Gold |\n| Ticket User | 600 + 7 tickets | Silver | ✅ Silver | Bronze → Silver (via points) |\n| Mixed Metrics | 1,850 + 120k sales | Gold | ✅ Gold | Bronze → **Skipped Silver** → Gold |\n\n### Transaction Type Coverage\n\n**Wallet Transactions by Type**:\n- **Points Earn/Base**: 64 transactions (17,250 points) ✅ Included in tier evaluation\n- **Points Earn/Bonus**: 8 transactions (5,900 points) ✅ Included in tier evaluation\n- **Points Earn/Reversal**: 5 transactions (-250 points) ✅ Correctly included (negative impact)\n- **Points Burn/Base**: 2 transactions (-1,200 points) ✅ Correctly excluded (reward redemptions)\n- **Tickets Earn**: 6 transactions (26 tickets) ✅ Included in tier evaluation\n- **Tickets Burn**: 2 transactions (-5 tickets) ✅ Correctly excluded (ticket redemptions)\n\n### Edge Cases Validated\n\n#### ✅ Tier Skipping Logic\n- **Bronze → Platinum**: High Performer earned 6,200 points, qualified for Platinum (5,000 threshold), skipped Gold (1,500 threshold)\n- **Bronze → Gold**: Multiple users earned 1,500+ points, skipped Silver (500 threshold)\n\n#### ✅ Maintenance Progress >100%\n- **Platinum User**: 206.67% maintenance (6,200 points ÷ 3,000 requirement)\n- **Business Logic**: Shows \"tier security\" - user has earned double the required points\n- **Customer Value**: Indicates high-value customers exceeding expectations\n\n#### ✅ Reversal Handling\n- **Correct Implementation**: `transaction_type = ''earn''`, `component = ''reversal''`, `signed_amount = negative`\n- **Tier Impact**: Properly reduces tier evaluation metrics\n- **vs Burn Transactions**: Reward redemptions correctly excluded from tier calculations\n\nThe tier management system is production-ready: real-time CDC-driven evaluation via the Render Background Worker, single Render Cron Job for the daily tier batch (apply pending + maintain/downgrade), single condition per tier, and a fresh `tier_progress` cache after every change. All tier flows go through two Render runtimes — `crm-event-processors` Worker (real-time, calls `process_tier_event`) and `tier-daily-batch` Cron Job (batch, calls `tier_apply_due_pending_upgrades` then `evaluate_and_apply_chunk` per chunk). Postgres is purely the write surface and the entry-point function host; it does not schedule anything for the tier system.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/Tier.md#L1936 Current Production Status & Test Validation", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d26a721b2681c9861df2300a2a5972b29288550fd9d6bdcc202174e6d26cf485", "truncated": false}, "is_active": true}, {"id": "a7c7e616-8981-59b6-a676-02ba0382e7c8", "feature_slug": "tiers", "title": "7. Business Rules", "content": "**Rule:** Upgrade conditions use OR logic. If a tier has multiple upgrade conditions, qualifying for any single one triggers the upgrade.\n**Example:** Gold requires \"500 points in 6 months\" OR \"฿10,000 sales in 12 months.\" A member earning 500 points but only ฿3,000 in sales still qualifies via the points path.\n\n**Rule:** The system evaluates upgrade tiers from highest ranking down. It stops at the first qualifying tier. Members can skip intermediate tiers.\n**Example:** Member is Bronze (rank 1). Platinum (rank 3) condition = 1000 points. Gold (rank 2) = 500 points. Member has 1200 points → upgrades directly to Platinum, skipping Gold.\n\n**Rule:** Downgrade evaluates only when the maintain deadline has arrived. Before the deadline, the member keeps their tier regardless of current metrics.\n**Example:** Member upgraded to Gold on Jan 1, maintain window = 12 months rolling. Even if they have 0 points in June, no downgrade until the maintain deadline (recorded in `tier_evaluation_tracking.maintain_deadline`).\n\n**Rule:** On downgrade, the member drops to the highest-ranking lower tier they qualify for. If they qualify for none, they drop to the entry tier.\n**Example:** Platinum member fails maintain → system checks Gold maintain conditions → passes → downgraded to Gold (not Bronze).\n\n**Rule:** Persona-scoped tiers are isolated. A member with persona \"Retailer\" is only evaluated against tiers where `persona_id` matches or is NULL.\n**Example:** \"Wholesaler Gold\" tier exists but a \"Retailer\" member will never be evaluated against it.\n\n**Rule:** Entry tier assignment happens on signup via trigger. The system finds the entry tier matching the user''s `user_type` and `persona_id` (with NULL as wildcard).\n**Example:** New buyer with \"Corporate\" persona → system looks for entry tier where `user_type=''buyer''` AND (`persona_id=''corporate-uuid''` OR `persona_id IS NULL`).\n\n**Rule:** Burn rate is tier-specific, not global. Each tier independently defines its conversion rate. A member''s burn rate changes immediately when their tier changes.\n**Example:** Silver burn_rate = 0.25, Gold = 0.50. Member upgrades Silver→Gold → their checkout discount doubles instantly.\n\n**Rule:** Progress tracking shows the single best upgrade path. When multiple conditions exist for the next tier, `upgrade_progress_percent` reflects whichever condition the member is closest to completing.\n**Example:** Gold has \"500 points\" (member at 60%) and \"฿10,000 sales\" (member at 80%). Progress shows 80%.\n\n**Rule:** Window date calculation varies by type. `rolling` looks back from today. `fixed_period` uses the MM-DD anchor. `anniversary` uses the member''s signup date. `calendar_month` and `calendar_quarter` snap to period boundaries.\n**Example:** For `calendar_quarter` evaluated on May 15: window = Apr 1 – Jun 30 (Q2).", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/tiers.md#L270 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8c283ef17bcaa477b4f6dc7c8840b6553b6a635627497bdb1a0feb719a3361d2", "truncated": false}, "is_active": true}, {"id": "ce40e8b4-ae33-5dcc-8bfd-da4a21d3dad5", "feature_slug": "tiers", "title": "3. Configuration Reference", "content": "### Tier Definition\n\n\n| Setting     | What it controls                          | Example                   | Default          |\n| ----------- | ----------------------------------------- | ------------------------- | ---------------- |\n| Tier name   | Display name                              | \"Gold\"                    | Required         |\n| User type   | Buyer or seller tier track                | `buyer`                   | `buyer`          |\n| Persona     | Scope tier to a persona (separate ladder) | \"Corporate\" persona       | NULL (universal) |\n| Ranking     | Position in hierarchy (higher = better)   | 2                         | 0                |\n| Entry tier  | Auto-assigned on signup                   | true                      | false            |\n| Burn rate   | Points-to-discount conversion             | 0.5 (1 pt = ฿0.50)        | NULL (disabled)  |\n| Icon        | Tier icon URL or emoji                    | `https://cdn.../gold.svg` | None             |\n| Color       | Tier color (hex)                          | `#FFD700`                 | None             |\n| Benefits    | JSONB describing tier perks               | `{\"free_shipping\": true}` | NULL             |\n| Card design | JSONB for member card styling             | `{\"bg_image\": \"...\"}`     | NULL             |\n\n\n### Upgrade Conditions\n\n\n| Setting                   | What it controls                             | Example       | Default   |\n| ------------------------- | -------------------------------------------- | ------------- | --------- |\n| Metric                    | What is measured                             | `points`      | `ticket`  |\n| Amount                    | Target threshold                             | 500           | 0         |\n| Window type               | Evaluation period calculation                | `rolling`     | `rolling` |\n| Window months             | Period length in months                      | 6             | —         |\n| Window start              | Start date for `fixed_period` (MM-DD format) | \"01-01\"       | —         |\n| Window start field        | User date field for `anniversary`            | `create_date` | —         |\n| Frequency                 | How often to evaluate                        | `realtime`    | —         |\n| Upgrade evaluation timing | When upgrade takes effect                    | —             | Immediate |\n\n\n### Maintain Conditions\n\nSame fields as upgrade conditions. The system checks maintain conditions when the maintain deadline arrives for a user.\n\n### Display Settings\n\n\n| Setting     | What it controls                  | Example                                      |\n| ----------- | --------------------------------- | -------------------------------------------- |\n| Icon        | Image URL or emoji for tier badge | `https://cdn.../platinum.svg`                |\n| Color       | Brand color for tier UI elements  | `#8B5CF6`                                    |\n| Benefits    | Structured perks description      | `{\"discount\": \"10%\", \"free_shipping\": true}` |\n| Card design | Member card visual configuration  | `{\"bg_image\": \"...\", \"text_color\": \"#FFF\"}`  |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/tiers.md#L45 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "tiers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8baa36dd48933eb65a982609807e488efd2e5128116865762662edd30125b429", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
